-- Isolated PostgreSQL fixture matching the relevant production LHI table contracts.
-- This file is used only by the disposable GitHub Actions PostgreSQL service.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $roles$
BEGIN
  CREATE ROLE anon NOLOGIN;
EXCEPTION WHEN duplicate_object THEN NULL;
END
$roles$;
DO $roles$
BEGIN
  CREATE ROLE authenticated NOLOGIN;
EXCEPTION WHEN duplicate_object THEN NULL;
END
$roles$;
DO $roles$
BEGIN
  CREATE ROLE service_role NOLOGIN BYPASSRLS;
EXCEPTION WHEN duplicate_object THEN NULL;
END
$roles$;

CREATE TABLE public.staff (
  staff_id text PRIMARY KEY,
  nama text NOT NULL,
  jabatan text,
  role text NOT NULL,
  bidang text,
  status text NOT NULL DEFAULT 'Aktif',
  auth_user_id uuid UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz,
  last_seen_at timestamptz,
  last_login_device text,
  lhi_manual_unblock_until timestamptz
);

CREATE TABLE public.reports (
  report_id text PRIMARY KEY,
  staff_id text NOT NULL REFERENCES public.staff(staff_id),
  tanggal date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE TABLE public.access_settings (
  key text PRIMARY KEY,
  value text,
  updated_at timestamptz,
  updated_by_staff_id text,
  updated_by_name text
);

CREATE TABLE public.lhi_discipline_incidents (
  incident_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  started_at timestamptz NOT NULL DEFAULT now(),
  deadline_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'GRACE',
  started_by_staff_id text,
  started_by_name text,
  completed_at timestamptz,
  reactivated_at timestamptz
);

CREATE TABLE public.lhi_discipline_obligations (
  obligation_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  incident_id bigint NOT NULL,
  staff_id text NOT NULL,
  required_date date NOT NULL,
  completed_at timestamptz
);

CREATE TABLE public.lhi_discipline_notifications (
  notification_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  event_key text NOT NULL,
  recipient_staff_id text NOT NULL,
  subject text NOT NULL,
  message text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz,
  UNIQUE (event_key, recipient_staff_id)
);

CREATE TABLE public.audit_log (
  audit_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "timestamp" timestamptz NOT NULL DEFAULT now(),
  username text,
  staff_id text,
  action text NOT NULL,
  report_id text,
  keterangan text,
  field_changed text,
  old_value text,
  new_value text,
  version_before integer,
  version_after integer
);

